        pcall(function()
            features.skinchanger:ApplyNow()
        end)
        task.wait(0.35)
        pcall(function()
            features.skinchanger:ApplyNow()
        end)
        task.wait(0.8)
        pcall(function()
            features.skinchanger:ApplyNow()
        end)
    end)
end

